from lib import R
SP = "79-soups-world.txt"; DR = "80-drinks-more.txt"
S = [
 ("Thai Coconut Chicken Soup (Tom Kha Gai)", "Thai", 15, 20, 4, "Soup, Lunch, Dinner", "500 g|chicken breast, sliced; 2 cans|coconut milk; 500 ml|chicken stock; 3 slices|galangal, or ginger; 2|lemongrass stalks, bruised; 5|kaffir lime leaves; 200 g|mushrooms, sliced; 3 tbsp|fish sauce; 2|limes; 1 tsp|sugar; 2|red chilies; 1 handful|cilantro", "Simmer the stock, coconut milk, galangal, lemongrass and lime leaves for 10 minutes / Add the chicken and mushrooms and simmer gently 8 minutes until cooked / Season with fish sauce, sugar and lime juice off the heat and top with chilies and cilantro"),
 ("Roman Egg Drop Soup (Stracciatella)", "Italian", 5, 10, 4, "Soup, Lunch", "1.2 l|chicken stock; 3|eggs; 40 g|parmesan, grated; 2 tbsp|semolina; 1 pinch|nutmeg; 1 handful|parsley; 100 g|spinach", "Bring the stock to a simmer and add the spinach / Beat the eggs, parmesan, semolina and nutmeg / Pour into the simmering stock while stirring gently so it forms soft strands; cook 1 minute and add parsley"),
 ("Scotch Broth", "Scottish", 20, 100, 6, "Soup, Dinner", "500 g|lamb neck, or shoulder; 80 g|pearl barley; 60 g|dried split peas, soaked; 2|carrots, diced; 1|onion, diced; 1|leek, sliced; 150 g|rutabaga, diced; 2 l|water; 1 handful|parsley; |salt", "Simmer the lamb, barley and peas in the water for 1 hour, skimming / Add the vegetables and simmer 40 minutes more / Lift out the lamb, shred the meat back in and season; scatter with parsley"),
 ("Colombian Chicken and Potato Soup (Ajiaco)", "Colombian", 20, 60, 6, "Soup, Dinner", "1 kg|chicken pieces; 1 kg|potatoes, half floury and sliced, half waxy and cubed; 3|corn cobs, in pieces; 2 l|chicken stock; 1 bunch|cilantro; 120 ml|heavy cream; 2 tbsp|capers; 1|avocado; |salt", "Simmer the chicken in the stock with the cilantro stems for 30 minutes, then shred it / Add the potatoes and corn and simmer 30 minutes so some potatoes break down to thicken / Return the chicken / Serve with cream, capers and avocado"),
 ("Ecuadorian Potato Cheese Soup (Locro de Papa)", "Ecuadorian", 15, 30, 4, "Soup, Lunch, Dinner", "1 kg|potatoes, cubed; 1|onion, chopped; 2 cloves|garlic; 1 tsp|cumin; 1 tsp|achiote, or paprika; 1 l|vegetable stock; 250 ml|milk; 150 g|queso fresco; 1|avocado; 2 tbsp|butter; 1 handful|cilantro", "Soften the onion and garlic in the butter with the cumin and achiote / Add the potatoes and stock and simmer 20 minutes, mashing some to thicken / Stir in the milk and most of the cheese and heat gently / Top with avocado, cilantro and more cheese"),
 ("Peruvian Chicken Cilantro Soup (Aguadito de Pollo)", "Peruvian", 15, 45, 6, "Soup, Dinner", "800 g|chicken thighs; 2 bunches|cilantro; 1|onion; 3 cloves|garlic; 2 tbsp|aji amarillo paste; 150 g|long-grain rice; 1|red bell pepper, diced; 150 g|frozen peas; 2|potatoes, diced; 1.5 l|chicken stock; 2 tbsp|vegetable oil; 1|lime", "Blend the cilantro with a little stock / Brown the chicken in the oil, add the onion, garlic and aji and cook 5 minutes / Add the stock, rice and potatoes and simmer 25 minutes / Add the cilantro puree, pepper and peas and cook 5 minutes; serve with lime"),
 ("Greek White Bean Soup (Fasolada)", "Greek", 15, 90, 6, "Soup, Dinner, Lunch", "500 g|dried white beans, soaked overnight; 1|onion, chopped; 2|carrots, sliced; 2|celery stalks, sliced; 2 tbsp|tomato paste; 1 can|canned tomatoes; 100 ml|olive oil; 1 tsp|oregano; 2|bay leaves; 1|lemon; |salt", "Simmer the drained beans in fresh water for 30 minutes and drain / Soften the vegetables in half the oil, add the tomato paste and tomatoes / Add the beans, bay, oregano and water to cover by 3 cm and simmer 1 hour until creamy / Stir in the rest of the oil and season; serve with lemon"),
 ("Korean Soybean Paste Stew (Doenjang Jjigae)", "Korean", 10, 20, 3, "Soup, Dinner", "3 tbsp|doenjang; 1 tbsp|gochujang; 600 ml|fish stock, or anchovy stock; 1|zucchini, cubed; 1|potato, cubed; 1|onion, chopped; 200 g|firm tofu, cubed; 100 g|mushrooms; 2 cloves|garlic; 1|green chili; 1|green onion", "Bring the stock to a boil and whisk in the doenjang and gochujang / Add the potato and onion and simmer 8 minutes / Add the zucchini, mushrooms, garlic and tofu and simmer 6 minutes / Add the chili and green onion and serve bubbling with rice"),
 ("South Indian Tomato Rasam", "South Indian", 10, 20, 4, "Soup, Side dish", "3|tomatoes, chopped; 2 tbsp|tamarind paste; 1 tsp|black pepper, crushed; 1 tsp|cumin seeds; 3 cloves|garlic, crushed; 0.25 tsp|turmeric; 1 tsp|rasam powder, opt; 1 tsp|mustard seeds; 10|curry leaves; 1 tbsp|ghee; 800 ml|water; 1 handful|cilantro; |salt", "Simmer the tomatoes, tamarind, pepper, cumin, garlic, turmeric, rasam powder, salt and water for 15 minutes / Fry the mustard seeds and curry leaves in the ghee until they pop and pour into the rasam / Add cilantro; serve as a thin soup or over rice"),
 ("Beef and Barley Soup", "American", 20, 90, 6, "Soup, Dinner", "600 g|beef chuck, cubed; 1|onion, chopped; 2|carrots, diced; 2|celery stalks, diced; 200 g|mushrooms, sliced; 120 g|pearl barley; 1.5 l|beef stock; 1 can|canned tomatoes; 1 tsp|thyme; 2 tbsp|vegetable oil; |salt", "Brown the beef in the oil, then add the onion, carrots, celery and mushrooms for 8 minutes / Add the stock, tomatoes and thyme and simmer covered for 45 minutes / Add the barley and simmer 40 minutes more until tender"),
 ("Caribbean Callaloo", "Trinidadian", 15, 30, 6, "Soup, Side dish", "500 g|spinach, or callaloo leaves; 200 g|okra, sliced; 1|onion, chopped; 3 cloves|garlic; 400 ml|coconut milk; 500 ml|vegetable stock; 1|scotch bonnet pepper, whole; 2 sprigs|thyme; 2 tbsp|butter; |salt", "Soften the onion and garlic in the butter / Add the greens, okra, coconut milk, stock, thyme and whole pepper and simmer 25 minutes / Remove the pepper and swizzle or blend until smooth"),
 ("Korean Rice Cake Soup (Tteokguk)", "Korean", 15, 25, 4, "Soup, Dinner", "500 g|korean rice cakes, sliced ovals; 200 g|beef, thinly sliced; 1.5 l|beef stock; 2 cloves|garlic; 2 tbsp|soy sauce; 1 tbsp|sesame oil; 2|eggs, beaten; 2|green onions; 1 sheet|nori, crumbled", "Soak the rice cakes in water for 20 minutes / Brown the beef in the sesame oil with the garlic, add the stock and soy sauce and simmer 15 minutes / Add the rice cakes and cook 5 minutes until soft and floating / Drizzle in the eggs, then top with green onions and nori"),
 ("Spanish Garlic Soup (Sopa de Ajo)", "Spanish", 10, 20, 4, "Soup, Lunch", "8 cloves|garlic, sliced; 4 tbsp|olive oil; 150 g|day-old bread, sliced; 2 tsp|smoked paprika; 1.2 l|chicken stock; 4|eggs; 2 slices|serrano ham, chopped, opt", "Fry the garlic gently in the oil until golden, add the bread and toast it in the oil / Stir in the paprika and pour in the stock; simmer 10 minutes / Crack in the eggs and poach 3 to 4 minutes / Scatter with ham"),
 ("Andalusian Salmorejo", "Spanish", 15, 0, 4, "Soup, Appetizer, Lunch", "1 kg|tomatoes, ripe; 150 g|day-old bread; 1 clove|garlic; 120 ml|olive oil; 1 tbsp|sherry vinegar; 2|eggs, hard-boiled; 50 g|serrano ham; |salt", "Blend the tomatoes, bread, garlic, vinegar and salt until very smooth / Blend in the oil slowly to a thick, creamy soup and chill 2 hours / Serve topped with chopped egg, ham and a drizzle of oil"),
 ("Creamy Carrot Soup with Cumin", "International", 10, 30, 4, "Soup, Lunch", "800 g|carrots, sliced; 1|onion, chopped; 1 tsp|cumin; 1 l|vegetable stock; 120 ml|coconut milk; 2 tbsp|olive oil; 1|orange, zested; |salt", "Soften the onion in the oil with the cumin / Add the carrots and stock and simmer 25 minutes until very soft / Blend with the coconut milk and orange zest and season"),
 ("Zucchini Basil Soup", "Italian", 10, 20, 4, "Soup, Lunch", "4|zucchini, sliced; 1|onion, chopped; 2 cloves|garlic; 1|potato, diced; 1 l|vegetable stock; 1 handful|basil; 40 g|parmesan; 2 tbsp|olive oil; |salt", "Soften the onion and garlic in the oil / Add the zucchini, potato and stock and simmer 15 minutes / Blend with the basil and parmesan and season"),
 ("Matzo Ball Soup", "Jewish", 20, 60, 6, "Soup, Dinner", "100 g|matzo meal; 3|eggs; 3 tbsp|vegetable oil, or schmaltz; 3 tbsp|chicken stock; 2 l|chicken stock; 2|carrots, sliced; 2|celery stalks, sliced; 300 g|cooked chicken, shredded; 1 handful|dill; |salt", "Mix the matzo meal, eggs, fat, 3 tbsp stock and salt and chill 30 minutes / Roll into 12 balls with wet hands and simmer in salted water, covered, for 30 to 40 minutes / Simmer the carrots and celery in the stock for 15 minutes, add the chicken and matzo balls and finish with dill"),
 ("Fish Soup with Saffron and Fennel", "French", 20, 30, 4, "Soup, Dinner", "600 g|white fish fillets, chunks; 200 g|shrimp; 1|fennel bulb, sliced; 1|onion, sliced; 2 cloves|garlic; 1 can|canned tomatoes; 1 pinch|saffron; 1 l|fish stock; 1|orange, peel strip; 3 tbsp|olive oil; 1 handful|parsley", "Soften the fennel, onion and garlic in the oil for 8 minutes / Add the tomatoes, saffron, orange peel and stock and simmer 15 minutes / Add the fish and shrimp and poach gently 5 minutes / Scatter with parsley and serve with crusty bread"),
 ("Indonesian Chicken Soup (Soto Ayam)", "Indonesian", 20, 45, 6, "Soup, Dinner", "1 kg|chicken pieces; 4|shallots; 4 cloves|garlic; 1 tbsp|ginger; 1 tsp|turmeric; 4|candlenuts, or macadamias; 2|lemongrass stalks; 4|kaffir lime leaves; 2 l|water; 200 g|rice vermicelli; 100 g|bean sprouts; 3|eggs, hard-boiled; 2 tbsp|fried shallots; 1|lime; 2 tbsp|vegetable oil; |salt", "Blend the shallots, garlic, ginger, turmeric and nuts to a paste and fry in the oil for 5 minutes / Add the chicken, lemongrass, lime leaves, water and salt and simmer 40 minutes / Shred the chicken / Serve the broth over noodles, sprouts, chicken and halved eggs with fried shallots and lime"),
]
for t, cu, p, c, s, meals, ings, steps in S: R(SP, t, "Soup", cu, p, c, s, meals, ings, steps)
D = [
 ("Turkish Ayran", "Turkish", 3, 0, 2, "300 g|yogurt; 300 ml|water, cold; 0.5 tsp|salt; 4|ice cubes; 2|mint leaves, opt", "Whisk the yogurt, water and salt until frothy / Pour over ice and add mint"),
 ("Arnold Palmer (Half Tea Half Lemonade)", "American", 10, 5, 4, "4|black tea bags; 500 ml|water, boiling; 4|lemons; 80 g|sugar; 500 ml|water, cold; 8|ice cubes", "Steep the tea in the boiling water for 5 minutes, remove and cool / Stir the lemon juice and sugar into the cold water until dissolved / Mix the tea and lemonade and serve over ice"),
 ("Strawberry Basil Shrub", "American", 10, 5, 8, "300 g|strawberries, sliced; 150 g|sugar; 150 ml|apple cider vinegar; 1 handful|basil; 1 l|sparkling water", "Crush the strawberries with the sugar and basil and leave 1 day in the fridge / Strain, pressing the fruit, and stir in the vinegar; keep chilled up to 2 weeks / Mix about 3 tbsp of shrub with sparkling water and ice per glass"),
 ("Ginger Honey Switchel", "American", 5, 0, 4, "1 l|water, cold; 4 tbsp|apple cider vinegar; 3 tbsp|honey; 1 tbsp|ginger, grated; 1|lemon", "Stir the vinegar, honey, ginger and lemon juice into the water until the honey dissolves / Chill 2 hours, strain and serve over ice"),
 ("Homemade Ginger Beer (Quick)", "Caribbean", 10, 10, 6, "100 g|ginger, grated; 150 g|sugar; 500 ml|water; 2|limes; 1 l|sparkling water", "Simmer the ginger, sugar and water for 10 minutes and steep until cool / Strain and add the lime juice / Mix 1 part syrup with 3 parts sparkling water over ice"),
 ("Jamaican Sorrel Drink", "Jamaican", 10, 10, 8, "60 g|hibiscus flowers, dried; 50 g|ginger, sliced; 1 stick|cinnamon; 4|cloves; 1.5 l|water; 180 g|sugar; 1|orange, peel", "Boil the water with the ginger, cinnamon, cloves and orange peel, then add the hibiscus and turn off the heat / Steep at least 4 hours or overnight / Strain, stir in the sugar and chill; serve over ice"),
 ("Mango Pineapple Smoothie", "International", 5, 0, 2, "200 g|mango, frozen; 150 g|pineapple; 1|banana; 250 ml|coconut water; 120 g|yogurt", "Blend everything until smooth / Add a splash more coconut water if too thick"),
 ("Classic Eggnog", "American", 10, 10, 6, "500 ml|milk; 250 ml|heavy cream; 4|egg yolks; 100 g|sugar; 0.5 tsp|nutmeg; 1 tsp|vanilla extract; 1 stick|cinnamon", "Heat the milk, cream, cinnamon and nutmeg until steaming / Whisk the yolks and sugar, pour on the hot milk while whisking and return to the pan / Stir over low heat until it coats a spoon, about 71 °C (160 °F), add the vanilla, strain and chill"),
 ("Mexican Spiced Coffee (Cafe de Olla)", "Mexican", 5, 10, 4, "1 l|water; 60 g|dark brown sugar, or piloncillo; 1 stick|cinnamon; 1|orange, peel strip; 2|cloves; 40 g|ground coffee", "Simmer the water with the sugar, cinnamon, orange peel and cloves for 5 minutes / Stir in the coffee, turn off the heat and steep 5 minutes / Strain through a fine sieve or filter and serve hot"),
 ("Chai Latte", "Indian", 5, 10, 2, "300 ml|milk; 200 ml|water; 2|black tea bags; 4|cardamom pods, crushed; 1 stick|cinnamon; 3 slices|ginger; 2 tbsp|honey", "Simmer the water with the spices for 5 minutes / Add the tea and milk and heat to steaming for 3 minutes / Strain, sweeten with honey and froth if you like"),
 ("Brown Sugar Bubble Tea", "Taiwanese", 10, 20, 2, "100 g|tapioca pearls; 80 g|brown sugar; 60 ml|water; 2|black tea bags; 300 ml|water, boiling; 300 ml|milk; 8|ice cubes", "Cook the tapioca pearls following the packet, about 15 minutes, and drain / Simmer the brown sugar and 60 ml water to a syrup and stir in the pearls / Brew strong tea with the boiling water and cool / Spoon the pearls and syrup into glasses, add ice, tea and milk"),
 ("Cucumber Lime Lemonade", "American", 10, 0, 4, "1|cucumber, chopped; 3|limes; 2|lemons; 80 g|sugar; 1 l|water, cold; 8|ice cubes", "Blend the cucumber with 250 ml of the water and strain / Stir the citrus juice and sugar into the rest of the water until dissolved / Mix with the cucumber juice and serve over ice"),
 ("Elderflower Spritzer", "British", 3, 0, 2, "60 ml|elderflower cordial; 400 ml|sparkling water; 1|lime; 8|ice cubes; 1 handful|mint", "Divide the cordial between two glasses with ice / Top with sparkling water / Add a squeeze of lime and mint"),
 ("Orange Cream Smoothie", "American", 5, 0, 2, "250 ml|orange juice; 150 g|yogurt; 120 ml|milk; 2 tsp|vanilla extract; 8|ice cubes; 1 tbsp|honey", "Blend everything until frothy / Serve at once"),
]
for t, cu, p, c, s, ings, steps in D: R(DR, t, "Drink", cu, p, c, s, "Drink", ings, steps)
